                .ReturnsAsync(new HttpResponseMessage(System.Net.HttpStatusCode.NotFound));

            // Act
            await mapPreview.Install("http://example.com", mockHttpClient.Object);

            // Assert
            Assert.Equal(MapStatus.DownloadError, mapPreview.Status);
        }

